// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes4 interfaceId) public {
        // The reference C supports the IERC165 interface id via ERC165Upgradeable, and the
        // IAccessControl interface id via AccessControlUpgradeable. The mutant removes the
        // AccessControl support, so for interfaceId == type(IAccessControl).interfaceId it
        // returns false where the reference returns true.
        bytes4 erc165Id = type(IERC165).interfaceId;
        bytes4 accessControlId = type(IAccessControl).interfaceId;

        bool ok;
        bool result;
        try c.supportsInterface(interfaceId) returns (bool r) {
            ok = true;
            result = r;
        } catch {
            ok = false;
        }

        if (ok && interfaceId == erc165Id) {
            assertTrue(result);
        }

        if (ok && interfaceId == accessControlId) {
            assertTrue(result);
        }

        // General rule: the reference C satisfies supportsInterface(id) == true
        // for id in {IERC165, IAccessControl}. The buggy M drops IAccessControl support
        // so supportsInterface(IAccessControl) becomes false, which violates the rule
        // for the fuzzed interfaceId == IAccessControl.
    }
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address callerConfirmation) external;
}
